describe('Notifications', () => {
    beforeEach(() => {
        cy.visit('/notifications');
        cy.login(); // Assuming there's a custom command for login
    });

    it('should mark all notifications as read successfully', () => {
        cy.get('.notification').should('have.class', 'unread').then((notifications) => {
            const unreadCount = notifications.length;
            cy.get('.mark-all-read-button').click();
            cy.get('.notification').should('have.class', 'read');
            cy.get('.notification').should('have.length', unreadCount);
        });
    });

    it('should display a message if there are no unread notifications', () => {
        cy.get('.notification').each(($el) => {
            cy.wrap($el).invoke('remove'); // Simulate all notifications being read
        });
        cy.get('.mark-all-read-button').click();
        cy.get('.no-unread-notifications-message').should('be.visible').and('contain', 'No unread notifications');
    });
});
